const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

async function waitForContainer(containerId, token, helpers) {
  let status = 'IN_PROGRESS';
  let attempts = 0;
  while ((status === 'IN_PROGRESS' || status === 'PENDING') && attempts < 30) {
    await sleep(2000);
    let res;
    try {
      res = await helpers.httpRequest({
        method: 'GET',
        url: `https://graph.facebook.com/v19.0/${containerId}`,
        qs: { fields: 'status_code', access_token: token }
      });
    } catch (e) {
      const errData = e.response && e.response.data ? e.response.data : e;
      throw new Error(`Error consultando estado del contenedor ${containerId}: ` + JSON.stringify(errData));
    }
    status = res.status_code;
    attempts++;
  }
  if (status !== 'FINISHED') {
    throw new Error(`El contenedor ${containerId} no terminó de procesarse. Estado final: ${status}`);
  }
}

