    ig_story_ids: storyIds.join(', '),
    ig_post_id: igPostId,
    file_id: f.id,
    fileId: f.id,
    FileID: f.id,
    file_name: f.name,
    fileName: f.name,
    timestamp: nowIso,
    from_webhook: Boolean(inputData.from_webhook)
  });
}

for (const f of storyFiles) {
  if (successfulStoryIds.includes(f.id)) {
    if (!feedFiles.some(feedF => feedF.id === f.id)) {
      allPublished.push({
        ig_story_ids: storyIds.join(', '),
        ig_post_id: igPostId,
        file_id: f.id,
        fileId: f.id,
        FileID: f.id,
        file_name: f.name,
        fileName: f.name,
        timestamp: nowIso,
        from_webhook: Boolean(inputData.from_webhook)
      });
    }
  }
}

if (allPublished.length === 0) {
  return [{ json: { 
    ig_post_id: igPostId,
    ig_story_ids: storyIds.join(', '),
    from_webhook: Boolean(inputData.from_webhook),
    status: 'no_publications_saved', 
    failed_stories: failedStories 
  }}];
}

const result = allPublished.map((item, index) => {
  if (index === 0) {
    return { json: { ...item, failed_stories: failedStories } };
  }
  return { json: item };
});

return result;

// ==========================================
// RECIBIR ARCHIVOS DESDE PORTAL WEB (app.crocscale.com)
// Soporta application/json y text/plain (CORS Simple Request)
// ==========================================
const raw = $input.first().json || {};
let body = raw.body !== undefined ? raw.body : raw;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {
    body = {};
  }
}

const uploads = Array.isArray(body.uploads) ? body.uploads : [];
const store = body.store || 'nnn';
const schedule = body.schedule || {};
const product = body.product || {};
const publishNow = Boolean(body.publishNow);
const caption = body.caption || '';

const defaultFeedFolder = '1Tqu0lGDDETlIwtpAA5w7zsjkgLtU8SVv'; // NNN.Public.2026
const defaultStoryFolder = '1WDQSvu9qvL7MadLJDuJwhrgf2XdRXd1T'; // NNN.Story.2026

const outItems = [];
for (let i = 0; i < uploads.length; i++) {
  const u = uploads[i];
  if (!u || !u.base64Data) continue;

  const cleanB64 = String(u.base64Data).includes(',')
    ? String(u.base64Data).split(',')[1]
    : String(u.base64Data);

  const buffer = Buffer.from(cleanB64, 'base64');
  const fileName = u.fileName || `post_${Date.now()}_${i}.jpg`;
  const mimeType = u.mimeType || (fileName.toLowerCase().endsWith('.mp4') ? 'video/mp4' : 'image/jpeg');

  const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);
  const role = u.role || 'feed';
  const folderId = u.folderId || (role === 'story' ? defaultStoryFolder : defaultFeedFolder);

  outItems.push({
    json: {
      uploadIdx: i,
      store,
      role,
      folderId,
      fileName,
      mimeType,
      isVideo: Boolean(u.isVideo) || /\.(mp4|mov)$/i.test(fileName),
      publishNow,
      caption,
      sku: product.sku || '',
      productName: product.name || '',
      price: product.price || '',
      variants: product.variants || '',
      features: product.features || '',
      scheduledDate: schedule.date || '',
      target: schedule.target || 'both'
    },
    binary: {
      data: binaryData
    }
  });
}

if (outItems.length === 0) {
  throw new Error('No se recibieron archivos válidos en uploads[] desde el portal.');
}

return outItems;

// ==========================================
// CONSOLIDAR ARCHIVOS SUBIDOS A GOOGLE DRIVE
// Y PREPARAR ESTRUCTURA SI EL USUARIO ELIGIÓ 'PUBLICAR AHORA'
// ==========================================
const uploadedItems = $input.all();
const prepItems = $('8a. Preparar Archivos del Portal').all();

const firstPrep = (prepItems[0] && prepItems[0].json) ? prepItems[0].json : {};
const publishNow = Boolean(firstPrep.publishNow);

const feedFiles = [];
const storyFiles = [];
const allUploaded = [];

for (let i = 0; i < uploadedItems.length; i++) {
  const up = uploadedItems[i].json || {};
  const meta = (prepItems[i] && prepItems[i].json) ? prepItems[i].json : firstPrep;
  const fileId = up.id;
  const fileName = up.name || meta.fileName || 'post.jpg';
  const role = meta.role || 'feed';

  if (fileId) {
    const fileObj = {
      id: String(fileId).trim(),
      name: String(fileName).trim(),
      role,
      folderId: meta.folderId || ''
    };
    allUploaded.push(fileObj);
    if (role === 'story') {
      storyFiles.push({ id: fileObj.id, name: fileObj.name });
    } else {
      feedFiles.push({ id: fileObj.id, name: fileObj.name });
    }
  }
}

const firstFeed = feedFiles[0] || storyFiles[0] || { id: '', name: '' };
const firstStory = storyFiles[0] || null;

return [{
  json: {
    from_webhook: true,
    publish_now: publishNow,
    has_post: true,
    is_feed_post: feedFiles.length > 0,
    id: firstFeed.id,
    name: firstFeed.name,
    file_id: firstFeed.id,
    file_name: firstFeed.name,
    feed_files: feedFiles,
    story_files: storyFiles,
    uploaded_files: allUploaded,
    tipo_publicacion: feedFiles.length > 1 ? 'carrusel' : 'post',
    media_count: feedFiles.length || storyFiles.length || 1,
    image_ids: feedFiles.map(f => f.id),
    image_names: feedFiles.map(f => f.name),
    story_id: firstStory ? firstStory.id : null,
    story_name: firstStory ? firstStory.name : null,
    producto: firstPrep.productName || 'Bross London / NNN',
    articulo: firstPrep.sku || '',
    modelo: firstPrep.productName ? `${firstPrep.productName} (${firstPrep.sku})` : (firstPrep.sku || ''),
    precio: firstPrep.price || '$59.000',
    caracteristicas: firstPrep.features || '',
    variantes: firstPrep.variants || 'Surtidas / Único',
    custom_caption: firstPrep.caption || '',
    scheduled_date: firstPrep.scheduledDate || '',
    target: firstPrep.target || 'both'
  }
}];
